css:
* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    margin: 0;
    padding: 0;
    width: 100%;
    font-family: Arial, Helvetica, sans-serif;
    color: #171717;
    background: #ffffff;
    overflow-x: hidden;
}

.hero {
    min-height: 100vh;
    color: white;

    background:
        linear-gradient(
            135deg,
            #111111,
            #10A37F
        );
}

.navbar {
    width: 100%;
    padding: 18px 16px;

    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-size: 18px;
    font-weight: bold;
}

.nav-links {
    display: none;
}

.hero-content {
    width: 100%;
    padding: 90px 20px 70px;
    text-align: center;
}

.eyebrow {
    color: #10A37F;
    font-size: 11px;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 1.5px;
}

.hero .eyebrow {
    color: #b8ffe9;
}

.hero h1 {
    margin: 18px 0;

    font-size: 42px;
    line-height: 1.08;

    word-wrap: break-word;
}

.hero p {
    font-size: 15px;
    line-height: 1.7;
    color: #dddddd;
}

.primary-button {
    display: inline-block;

    margin-top: 18px;
    padding: 13px 20px;

    border: none;
    border-radius: 9px;

    background: #10A37F;
    color: white;

    text-decoration: none;

    cursor: pointer;

    font-weight: bold;
}

.section {
    width: 100%;
    padding: 65px 20px;
    text-align: center;
}

.section h2 {
    margin: 10px 0 18px;
    font-size: 32px;
    line-height: 1.15;
}

.section > p:not(.eyebrow) {
    width: 100%;
    margin: auto;

    color: #666;
    line-height: 1.7;
    font-size: 14px;
}

.light-section {
    background: #f5f7f6;
}

.cards {
    width: 100%;
    margin-top: 35px;

    display: flex;
    flex-direction: column;

    gap: 16px;
}

.card {
    width: 100%;

    background: white;

    padding: 25px 20px;

    border-radius: 15px;

    box-shadow:
        0 8px 30px
        rgba(0, 0, 0, 0.08);
}

.card-icon {
    font-size: 26px;
    color: #10A37F;
}

.card h3 {
    margin: 13px 0 8px;
}

.card p {
    color: #777;
    line-height: 1.6;
    font-size: 14px;
}

.contact-section {
    min-height: 430px;

    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
}

footer {
    padding: 30px 20px;

    text-align: center;

    background: #111111;
    color: white;
}

footer p {
    color: #888;
    font-size: 12px;
}

@media (min-width: 501px) {

    body {
        display: flex;
        justify-content: center;
        background: #151515;
    }

    .hero,
    .section,
    footer {
        max-width: 500px;
    }

    .hero {
        width: 100%;
    }

    .cards {
        flex-direction: column;
    }
}

